/** void GetBg0TilesDst(u16 **tilemap, u16 **tileset) */
export function GetBg0TilesDst(tilemap: any, tileset: any): any {
  let screenBase: any = REG_BG0CNT >> 8;
      let charBase: any = REG_BG0CNT >> 2;

      screenBase <<= 11;
      charBase <<= 14;

      tilemap = (BG_VRAM + screenBase);
      tileset = (BG_VRAM + charBase);
}

